def solve(g, firsthit=False, bounce=True):
    H,W=len(g),len(g[0]); out=[row[:] for row in g]
    comps=[]; seen=set()
    for i in range(H):
        for j in range(W):
            if g[i][j]!=0 and (i,j) not in seen:
                st=[(i,j)]; comp=[]; seen.add((i,j))
                while st:
                    r,c=st.pop(); comp.append((r,c))
                    for dr,dc in((-1,0),(1,0),(0,-1),(0,1)):
                        x,y=r+dr,c+dc
                        if 0<=x<H and 0<=y<W and g[x][y]==8 and (x,y) not in seen:
                            seen.add((x,y)); st.append((x,y))
                comps.append(comp)
    points=[(r,c,g[r][c]) for r in range(H) for c in range(W) if g[r][c] not in (0,8)]
    dirs=[(-1,-1),(-1,1),(1,-1),(1,1)]
    def pos(r,c,d,k,bounce,H_,W_):
        while 0<=r<H_ and 0<=c<W_:
            yield (r,c); r+=d[0]; c+=d[1]
            if bounce and not (0<=r<H_ and 0<=c<W_): r-=d[0]; c-=d[1]
    # variant: bounce off walls (reflect)
    def move(r,c,d,H_,W_):
        while 0<=r<H_ and 0<=c<W_:
            yield (r,c)
            r+=d[0]; c+=d[1]
            if r==H_: d[0]=-1
            elif r==-1: d[0]=1
            if c==W_: d[1]=-1
            elif c==-1: d[1]=1
    for pr,pc,pv in points:
        for d in dirs:
            for (r,c) in move(pr,pc,d,H,W):
                if (r,c) in {q for cs in comps for q in cs}:
                    out[r][c]=pv; break
    return out

